/* @lc app=leetcode id=2736 lang=kotlin */
class Solution { fun maximumSumQueries(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): IntArray = nums1.indices.map { intArrayOf(nums1[it], nums2[it]) }.sortedByDescending { it[0] }.let { pairs -> queries.indices.map { intArrayOf(queries[it][0], queries[it][1], it) }.sortedByDescending { it[0] }.let { qs -> IntArray(queries.size).let { ans -> java.util.ArrayList<IntArray>().let { stack -> IntArray(1).let { pIdx -> qs.forEach { q -> q[0].let { minX -> q[1].let { minY -> q[2].let { originalIdx -> generateSequence { if (pIdx[0] < pairs.size && pairs[pIdx[0]][0] >= minX) pairs[pIdx[0]].let { p -> generateSequence { if (stack.isNotEmpty() && stack.last()[1] <= p[0] + p[1]) stack.removeAt(stack.size - 1) else null }.count().let { if (stack.isEmpty() || stack.last()[0] < p[1]) stack.add(intArrayOf(p[1], p[0] + p[1])) }.also { pIdx[0] = pIdx[0] + 1 } } else null }.count().let { ans.set(originalIdx, generateSequence(Triple(0, stack.size - 1, -1)) { (low, high, best) -> if (low > high) null else ((low + high) / 2).let { mid -> if (stack[mid][0] >= minY) Triple(low, mid - 1, stack[mid][1]) else Triple(mid + 1, high, best) } }.last().third) } } } } } ans } } } } } }